def solve(params):
    import math
    slots=params['slots']
    values=params['values']
    if not values:
        return 0
    n=len(values)
    if slots>=n:
        return max(values)
    if slots==1:
        return sum(values)
    vals=sorted(values, reverse=True)
    total=sum(vals)
    lo=max(vals[0], (total+slots-1)//slots)
    hi=total
    def can_pack(limit):
        if total > limit*slots:
            return False
        bins=[0]*slots
        # depth-first with pruning and duplicate-bin skipping
        from functools import lru_cache
        # use recursion with sorting bins to avoid permutations
        def dfs(idx):
            if idx==n:
                return True
            v=vals[idx]
            seen=set()
            for i in range(slots):
                if bins[i]+v <= limit and bins[i] not in seen:
                    seen.add(bins[i])
                    bins[i]+=v
                    if dfs(idx+1):
                        return True
                    bins[i]-=v
                    # if bin was empty, no need to try other empty bins
                    if bins[i]==0:
                        break
            return False
        return dfs(0)
    while lo < hi:
        mid=(lo+hi)//2
        if can_pack(mid):
            hi=mid
        else:
            lo=mid+1
    return lo

