def solve(params):
    import math, itertools
    slots=params['slots']
    values=params['values']
    if not values:
        return 0
    n=len(values)
    if slots>=n:
        return max(values)
    if slots==1:
        return sum(values)
    lo=max(max(values), (sum(values)+slots-1)//slots)
    hi=sum(values)
    def can_pack_bruteforce(limit):
        vals=list(values)
        # exhaustive search over assignments using recursion without pruning
        bins=[0]*slots
        # simple recursive brute force trying every bin for each item
        def dfs(idx):
            if idx==n:
                return True
            v=vals[idx]
            for b in range(slots):
                if bins[b]+v <= limit:
                    bins[b]+=v
                    if dfs(idx+1):
                        return True
                    bins[b]-=v
            return False
        return dfs(0)
    for k in range(lo, hi+1):
        if can_pack_bruteforce(k):
            return k
    return hi
